<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api,http } from '@/api/http'
import type { PageData,Product,Supplier } from '@/types'
import { ElMessage,ElMessageBox } from 'element-plus'
import { Delete,Plus } from '@element-plus/icons-vue'
const list=ref<any[]>([]),products=ref<Product[]>([]),suppliers=ref<Supplier[]>([]),page=ref(1),total=ref(0),status=ref(''),loading=ref(false),dialog=ref(false),detailDialog=ref(false),detail=ref<any>(),form=reactive<any>({supplierId:null,remark:'',items:[{productId:null,quantity:1,unitPrice:0}]})
const amount=computed(()=>form.items.reduce((sum:number,x:any)=>sum+Number(x.quantity||0)*Number(x.unitPrice||0),0))
async function load(){loading.value=true;try{const d=await api<PageData<any>>(http.get('/purchases',{params:{status:status.value,page:page.value,pageSize:15}}));list.value=d.items;total.value=d.total}finally{loading.value=false}}
async function prepare(){const [p,s]=await Promise.all([api<PageData<Product>>(http.get('/catalog/products',{params:{pageSize:100}})),api<Supplier[]>(http.get('/suppliers/enabled'))]);products.value=p.items;suppliers.value=s}
function open(){Object.assign(form,{supplierId:suppliers.value[0]?.id||null,remark:'',items:[{productId:null,quantity:1,unitPrice:0}]});dialog.value=true}
function choose(line:any){const p=products.value.find(x=>x.id===line.productId);if(p)line.unitPrice=p.purchasePrice}
async function save(){if(!form.supplierId||form.items.some((x:any)=>!x.productId||x.quantity<1)){ElMessage.warning('请选择供应商并完整填写明细');return}await api(http.post('/purchases',form));ElMessage.success('采购单已创建');dialog.value=false;load()}
async function view(row:any){detail.value=await api(http.get(`/purchases/${row.id}`));detailDialog.value=true}
async function confirm(row:any){await ElMessageBox.confirm(`确认采购单 ${row.orderNo} 入库？确认后将立即增加库存且不可重复。`,'确认入库',{type:'warning'});await api(http.post(`/purchases/${row.id}/confirm`));ElMessage.success('已入库并生成库存流水');load()}
async function cancel(row:any){await ElMessageBox.confirm(`确认取消采购单 ${row.orderNo}？`,'取消采购单');await api(http.post(`/purchases/${row.id}/cancel`));ElMessage.success('采购单已取消');load()}
onMounted(async()=>{await Promise.all([load(),prepare()])})
</script>
<template><div><div class="page-head"><div><h2>采购入库</h2><p>采购单确认时通过事务一次性更新库存，并以采购明细作为幂等业务键。</p></div><el-button type="primary" :icon="Plus" @click="open">新建采购单</el-button></div><section class="panel"><div class="toolbar"><el-select v-model="status" placeholder="全部状态" clearable style="width:160px" @change="page=1;load()"><el-option label="草稿" value="DRAFT"/><el-option label="已入库" value="WAREHOUSED"/><el-option label="已取消" value="CANCELLED"/></el-select></div><el-table v-loading="loading" :data="list" stripe><el-table-column prop="orderNo" label="采购单号" min-width="190"/><el-table-column prop="supplierName" label="供应商" min-width="180"/><el-table-column label="金额" width="120"><template #default="s"><strong>¥{{ Number(s.row.totalAmount).toFixed(2) }}</strong></template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.status==='WAREHOUSED'?'success':s.row.status==='CANCELLED'?'info':'warning'">{{ {'DRAFT':'草稿','WAREHOUSED':'已入库','CANCELLED':'已取消'}[s.row.status] }}</el-tag></template></el-table-column><el-table-column prop="creatorName" label="创建人" width="110"/><el-table-column prop="createdAt" label="创建时间" min-width="170"/><el-table-column label="操作" width="200" fixed="right"><template #default="s"><el-button link @click="view(s.row)">详情</el-button><el-button v-if="s.row.status==='DRAFT'" link type="primary" @click="confirm(s.row)">确认入库</el-button><el-button v-if="s.row.status==='DRAFT'" link type="danger" @click="cancel(s.row)">取消</el-button></template></el-table-column></el-table><el-pagination style="margin-top:18px;justify-content:flex-end" background layout="total,prev,pager,next" :total="total" :page-size="15" v-model:current-page="page" @current-change="load"/></section><el-dialog v-model="dialog" title="新建采购单" width="760px"><el-form label-position="top"><el-form-item label="供应商" required><el-select v-model="form.supplierId" filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="`${s.code} · ${s.name}`" :value="s.id"/></el-select></el-form-item><el-form-item label="采购明细" required><div style="width:100%"><div v-for="(line,index) in form.items" :key="index" style="display:grid;grid-template-columns:1fr 110px 150px 36px;gap:8px;margin-bottom:9px"><el-select v-model="line.productId" filterable placeholder="选择商品" @change="choose(line)"><el-option v-for="p in products" :key="p.id" :label="`${p.code} · ${p.name}`" :value="p.id"/></el-select><el-input-number v-model="line.quantity" :min="1" controls-position="right"/><el-input-number v-model="line.unitPrice" :min="0" :precision="2" controls-position="right"/><el-button circle :icon="Delete" :disabled="form.items.length===1" @click="form.items.splice(index,1)"/></div><el-button text type="primary" :icon="Plus" @click="form.items.push({productId:null,quantity:1,unitPrice:0})">添加一行</el-button></div></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item><div class="cart-total"><span>采购总额</span><strong>¥{{ amount.toFixed(2) }}</strong></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">创建草稿</el-button></template></el-dialog><el-dialog v-model="detailDialog" title="采购单详情" width="720px"><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="采购单号">{{ detail.orderNo }}</el-descriptions-item><el-descriptions-item label="状态">{{ detail.status }}</el-descriptions-item><el-descriptions-item label="供应商">{{ detail.supplierName }}</el-descriptions-item><el-descriptions-item label="总额">¥{{ detail.totalAmount }}</el-descriptions-item></el-descriptions><el-table :data="detail?.items||[]" style="margin-top:16px"><el-table-column prop="productCode" label="编码"/><el-table-column prop="productName" label="商品"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="unitPrice" label="单价"/><el-table-column prop="amount" label="金额"/></el-table></el-dialog></div></template>
